import { QueryClient, QueryClientProvider, useQueryClient } from '@tanstack/react-query';
import { useEffect, useMemo, useState, type ReactNode, type FormEvent } from 'react';
import { Link, Redirect, Route, Switch, useLocation, useParams } from 'wouter';
import { Activity, ArrowRight, BarChart3, CalendarDays, Check, ChevronRight, CircleHelp, Copy, Dumbbell, Flame, LayoutDashboard, LogOut, Menu, Moon, Plus, Search, Settings as SettingsIcon, Sun, Target, UserRound, Users, X } from 'lucide-react';
import {
  useAddExercise, useCompleteProfile, useCreateExerciseLibraryItem, useCreateSession, useDeleteAthlete, useDeleteExercise, useDeleteSession, useGetAthlete, useGetAthleteStats, useGetCurrentUser, useGetDashboard, useGetProgram, useGetSession, useGetSetupStatus, useListAthletes, useListExerciseLibrary, useListSessions, useLogExercise, useLogin, useLogout, useRegister, useUpdateAthlete, useUpdateExercise, useUpdateSession,
  getGetAthleteQueryKey, getGetAthleteStatsQueryKey, getGetCurrentUserQueryKey, getGetDashboardQueryKey, getGetProgramQueryKey, getGetSessionQueryKey, getListAthletesQueryKey, getListExerciseLibraryQueryKey, getListSessionsQueryKey,
} from '@/lib/local-api';
import type { Athlete, AuthUser, Exercise, ExerciseLibraryItem, PersonalRecords, Stats, TrainingSession } from '@/lib/local-api';
import { ErrorBoundary } from '@/components/error-boundary';
import { Toaster } from '@/components/ui/toaster';
import { TooltipProvider } from '@/components/ui/tooltip';
import { Router as WouterRouter } from 'wouter';

const queryClient = new QueryClient();
const nav = [
  { href: '/coach', label: 'Overview', icon: LayoutDashboard },
  { href: '/athletes', label: 'Athletes', icon: Users },
  { href: '/calendar', label: 'Calendar', icon: CalendarDays },
  { href: '/exercises', label: 'Exercise library', icon: Dumbbell },
  { href: '/progress', label: 'Progress', icon: BarChart3 },
];

function initials(first?: string, last?: string) { return `${first?.[0] ?? ''}${last?.[0] ?? ''}`.toUpperCase(); }
function dateLabel(value?: string | null) { return value ? new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric' }) : '—'; }
function cx(...v: Array<string | false | null | undefined>) { return v.filter(Boolean).join(' '); }

function Logo({ light = false }: { light?: boolean }) {
  return <Link href="/coach" className={cx('flex items-center gap-3', light ? 'text-slate-100' : 'text-foreground')} data-testid="link-logo">
    <span className="grid h-9 w-9 place-items-center rounded-xl bg-primary text-primary-foreground shadow-sm"><span className="font-mono text-xs font-bold">SN</span></span>
    <span><span className="block text-sm font-extrabold tracking-[.18em]">SN POWER</span><span className="block text-[9px] uppercase tracking-[.22em] opacity-55">training systems</span></span>
  </Link>;
}

function Button({ children, className = '', variant = 'primary', ...props }: { children: ReactNode; className?: string; variant?: 'primary' | 'quiet' | 'outline' | 'danger'; [key: string]: unknown }) {
  return <button className={cx('inline-flex items-center justify-center gap-2 rounded-xl px-4 py-2.5 text-sm font-bold', variant === 'primary' && 'bg-primary text-primary-foreground hover:brightness-95', variant === 'quiet' && 'bg-secondary text-secondary-foreground hover:bg-muted', variant === 'outline' && 'border border-border bg-card text-foreground hover:bg-muted', variant === 'danger' && 'bg-destructive text-destructive-foreground', className)} {...props}>{children}</button>;
}
function Card({ children, className = '', ...props }: { children: ReactNode; className?: string; [key: string]: unknown }) { return <section className={cx('rounded-2xl border border-card-border bg-card shadow-sm', className)} {...props}>{children}</section>; }
function Stat({ label, value, detail, tone = 'primary' }: { label: string; value: string | number; detail?: string; tone?: string }) {
  return <Card className="p-5"><div className="flex items-start justify-between"><p className="text-xs font-bold uppercase tracking-[.14em] text-muted-foreground">{label}</p><span className={cx('h-2 w-2 rounded-full', tone === 'accent' ? 'bg-accent' : tone === 'teal' ? 'bg-chart-3' : 'bg-primary')} /></div><p className="mt-4 text-3xl font-extrabold tracking-tight" data-testid={`stat-${label.toLowerCase().replaceAll(' ', '-')}`}>{value}</p>{detail && <p className="mt-1 text-xs text-muted-foreground">{detail}</p>}</Card>;
}
function Skeleton({ className = '' }: { className?: string }) { return <div className={cx('animate-pulse rounded-xl bg-muted', className)} />; }
function Empty({ title, body, action }: { title: string; body: string; action?: ReactNode }) { return <div className="sn-grid flex min-h-[240px] flex-col items-center justify-center rounded-2xl border border-dashed border-border p-8 text-center"><Target className="mb-3 h-8 w-8 text-primary" /><h3 className="font-extrabold">{title}</h3><p className="mt-1 max-w-sm text-sm text-muted-foreground">{body}</p>{action && <div className="mt-5">{action}</div>}</div>; }

/** Shared fields for personal records + "training since". Reused by the mandatory onboarding step and by Settings. */
function RecordsFields({ user, isAthlete }: { user?: { records: PersonalRecords; powerliftingSince: string | null }; isAthlete: boolean }) {
  return <>
    <div><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Current best lifts (kg) — leave blank if unsure, you can add these later</span>
      <div className="grid grid-cols-3 gap-3">
        <input name="squat" type="number" step="0.5" defaultValue={user?.records.squat ?? ''} placeholder="Squat" className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-record-squat" />
        <input name="bench" type="number" step="0.5" defaultValue={user?.records.bench ?? ''} placeholder="Bench" className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-record-bench" />
        <input name="deadlift" type="number" step="0.5" defaultValue={user?.records.deadlift ?? ''} placeholder="Deadlift" className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-record-deadlift" />
      </div>
    </div>
    <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{isAthlete ? 'Training since (powerlifting)' : 'Coaching / lifting since'}</span><input name="powerliftingSince" type="month" defaultValue={user?.powerliftingSince ?? ''} className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-powerlifting-since" /></label>
  </>;
}

function OnboardingPage({ user }: { user: AuthUser }) {
  const complete = useCompleteProfile();
  const [error, setError] = useState('');
  const isAthlete = user.role === 'athlete';
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    complete.mutate({
      data: {
        category: String(f.get('category') || '') || null,
        bodyWeight: Number(f.get('bodyWeight')) || null,
        records: { squat: Number(f.get('squat')) || null, bench: Number(f.get('bench')) || null, deadlift: Number(f.get('deadlift')) || null },
        powerliftingSince: String(f.get('powerliftingSince') || '') || null,
      },
    }, { onError: () => setError('Could not save your profile.') });
  };
  return <AuthShell eyebrow="One last step" title={<>Welcome, {user.firstName}.</>}>
    <p className="mt-2 text-sm text-muted-foreground">{isAthlete ? 'A couple of details so your coach can build the right program for you.' : 'A couple of details to finish setting up your coaching profile.'}</p>
    <form onSubmit={submit} className="mt-8 space-y-4">
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{isAthlete ? 'Weight class / category' : 'Coaching focus'}</span><input name="category" required placeholder={isAthlete ? 'e.g. -93 kg' : 'e.g. Powerlifting, strength & conditioning'} className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-profile-category" /></label>
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Body weight (kg){!isAthlete && ' — optional'}</span><input name="bodyWeight" type="number" step="0.1" required={isAthlete} className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-profile-bodyweight" /></label>
      <RecordsFields isAthlete={isAthlete} />
      {error && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive" data-testid="status-profile-error">{error}</p>}
      <Button className="w-full py-3" type="submit" disabled={complete.isPending} data-testid="button-profile-submit">{complete.isPending ? 'Saving…' : 'Save and continue'}</Button>
    </form>
  </AuthShell>;
}

function Shell({ children }: { children: ReactNode }) {
  const [location, setLocation] = useLocation();
  const [mobileOpen, setMobileOpen] = useState(false);
  const [theme, setTheme] = useState(() => localStorage.getItem('sn-theme') || 'light');
  const { data: user, isLoading } = useGetCurrentUser();
  useEffect(() => { document.documentElement.classList.toggle('dark', theme === 'dark' || (theme === 'system' && matchMedia('(prefers-color-scheme: dark)').matches)); localStorage.setItem('sn-theme', theme); }, [theme]);
  const logout = useLogout();
  const isAthlete = location.startsWith('/athlete');
  const items = isAthlete ? [
    { href: '/athlete', label: 'Today', icon: Target }, { href: '/athlete/progress', label: 'My progress', icon: BarChart3 }, { href: '/settings', label: 'Settings', icon: SettingsIcon },
  ] : nav.concat({ href: '/settings', label: 'Settings', icon: SettingsIcon });
  if (isLoading) return <div className="grid min-h-[100dvh] place-items-center bg-background"><Skeleton className="h-12 w-48" /></div>;
  if (!user) return <Redirect to="/login" />;
  if (!user.profileComplete) return <OnboardingPage user={user} />;
  return <div className="sn-noise min-h-[100dvh] bg-background text-foreground">
    <aside className={cx('fixed inset-y-0 left-0 z-40 flex w-[250px] flex-col border-r border-sidebar-border bg-sidebar px-4 py-5 text-sidebar-foreground transition-transform md:translate-x-0', mobileOpen ? 'translate-x-0' : '-translate-x-full')}>
      <div className="px-2"><Logo light /></div>
      <div className="mt-10 flex-1"><p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.2em] opacity-45">{isAthlete ? 'Athlete space' : 'Coach workspace'}</p><nav className="space-y-1">{items.map(item => <Link key={item.href} href={item.href} onClick={() => setMobileOpen(false)} className={cx('flex items-center gap-3 rounded-xl px-3 py-3 text-sm font-semibold opacity-65 hover:bg-sidebar-accent hover:opacity-100', location === item.href && 'bg-sidebar-primary text-sidebar-primary-foreground opacity-100')} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`}><item.icon className="h-[17px] w-[17px]" />{item.label}</Link>)}</nav></div>
      <div className="rounded-2xl border border-sidebar-border bg-sidebar-accent p-3"><p className="text-xs font-bold">Training week</p><p className="mt-1 text-[11px] opacity-55">Keep the signal high. Log the work.</p><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-sidebar"><div className="h-full w-[72%] rounded-full bg-sidebar-primary" /></div><p className="mt-2 font-mono text-[10px] opacity-55">72% COMPLETE</p></div>
      <div className="mt-4 flex items-center gap-3 border-t border-sidebar-border pt-4"><div className="grid h-9 w-9 place-items-center rounded-full bg-sidebar-primary font-bold text-sidebar-primary-foreground">{initials(user?.firstName, user?.lastName) || 'SP'}</div><div className="min-w-0 flex-1"><p className="truncate text-xs font-bold">{user?.firstName || 'Demo'} {user?.lastName || 'User'}</p><p className="truncate text-[10px] opacity-50">{user?.role === 'athlete' ? 'Athlete' : 'Head coach'}</p></div><button onClick={() => logout.mutate()} className="opacity-60 hover:opacity-100" data-testid="button-logout"><LogOut className="h-4 w-4" /></button></div>
    </aside>
    <div className="md:pl-[250px]"><header className="sticky top-0 z-30 flex h-[68px] items-center justify-between border-b border-border/70 bg-background/85 px-5 backdrop-blur-xl md:px-8"><button className="md:hidden" onClick={() => setMobileOpen(!mobileOpen)} data-testid="button-mobile-menu"><Menu className="h-5 w-5" /></button><div className="hidden items-center gap-2 text-sm text-muted-foreground md:flex"><span className="font-mono text-[10px]">SN /</span><span className="font-semibold capitalize">{location.split('/')[1] || 'overview'}</span></div><div className="ml-auto flex items-center gap-2"><Link href="/install" className="hidden rounded-lg px-3 py-2 text-xs font-bold text-muted-foreground hover:bg-muted sm:block" data-testid="link-install">Install app</Link><button onClick={() => setTheme(theme === 'dark' ? 'light' : 'dark')} className="grid h-9 w-9 place-items-center rounded-xl hover:bg-muted" data-testid="button-theme-toggle">{theme === 'dark' ? <Sun className="h-4 w-4" /> : <Moon className="h-4 w-4" />}</button><button className="grid h-9 w-9 place-items-center rounded-xl hover:bg-muted" data-testid="button-help"><CircleHelp className="h-4 w-4" /></button></div></header><main className="mx-auto max-w-[1440px] p-5 md:p-8">{children}</main></div>
  </div>;
}

function PageHead({ eyebrow, title, body, action }: { eyebrow?: string; title: string; body?: string; action?: ReactNode }) { return <div className="mb-8 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="font-mono text-[10px] font-medium uppercase tracking-[.22em] text-accent">{eyebrow || 'SN POWER'}</p><h1 className="mt-2 text-3xl font-extrabold tracking-[-.04em] md:text-4xl">{title}</h1>{body && <p className="mt-2 max-w-xl text-sm text-muted-foreground">{body}</p>}</div>{action}</div>; }

function CoachDashboard() {
  const { data, isLoading, isError, refetch } = useGetDashboard();
  const { data: athletes } = useListAthletes();
  if (isLoading) return <DashboardLoading />;
  if (isError) return <ErrorState retry={refetch} />;
  return <div className="sn-enter"><PageHead eyebrow="Monday · 06:42" title="Good morning, coach." body="A clear view of the work ahead. Keep today deliberate." action={<Link href="/athletes" className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-manage-athletes">Manage athletes <ArrowRight className="h-4 w-4" /></Link>} />
    <div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><Stat label="Active athletes" value={data?.activeAthleteCount ?? 0} detail={`${data?.athleteCount ?? 0} total roster`} /><Stat label="Sessions today" value={data?.sessionsToday ?? 0} detail={`${data?.completedToday ?? 0} already completed`} tone="accent" /><Stat label="Weekly volume" value={`${((data?.volumeThisWeek ?? 0) / 1000).toFixed(1)}k`} detail="kg moved across roster" tone="teal" /><Stat label="Avg. adherence" value="87.4%" detail="last 4 training weeks" /></div>
    <div className="mt-6 grid gap-6 xl:grid-cols-[1.35fr_.65fr]"><Card className="overflow-hidden"><div className="flex items-center justify-between border-b border-border px-5 py-4"><div><h2 className="font-extrabold">Roster pulse</h2><p className="mt-1 text-xs text-muted-foreground">The athletes who need your eye this week.</p></div><Link href="/athletes" className="text-xs font-bold text-accent" data-testid="link-roster-view">View roster</Link></div><div className="divide-y divide-border">{(athletes || []).slice(0, 5).map((a: Athlete) => <AthleteRow key={a.id} athlete={a} />)}{!athletes?.length && <div className="p-6"><Empty title="Your roster is quiet" body="Add your first athlete to start programming." action={<Link href="/athletes" className="text-sm font-bold text-accent">Add athlete</Link>} /></div>}</div></Card><Card className="p-5"><div className="flex items-center justify-between"><div><h2 className="font-extrabold">Recent activity</h2><p className="mt-1 text-xs text-muted-foreground">Signals from your workspace.</p></div><Activity className="h-5 w-5 text-muted-foreground" /></div><div className="mt-5 space-y-5">{(data?.recentActivity || []).slice(0, 5).map(item => <div className="flex gap-3" key={item.id} data-testid={`activity-${item.id}`}><span className="mt-1.5 h-2 w-2 shrink-0 rounded-full bg-primary" /><div><p className="text-sm font-semibold">{item.label}</p><p className="mt-0.5 text-xs text-muted-foreground">{item.detail}</p><p className="mt-1 font-mono text-[10px] uppercase text-muted-foreground">{dateLabel(item.date)}</p></div></div>)}{!data?.recentActivity?.length && <p className="py-8 text-sm text-muted-foreground">No activity yet.</p>}</div></Card></div>
  </div>;
}
function AthleteRow({ athlete, onEdit }: { athlete: Athlete; onEdit: () => void }) { return <div className="flex items-center gap-2 px-5 py-2 hover:bg-muted/60"><Link href={`/athletes/${athlete.id}`} className="flex min-w-0 flex-1 items-center gap-4 py-2" data-testid={`row-athlete-${athlete.id}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-secondary text-xs font-extrabold">{initials(athlete.firstName, athlete.lastName)}</div><div className="min-w-0 flex-1"><p className="font-bold">{athlete.firstName} {athlete.lastName}</p><p className="text-xs text-muted-foreground">{athlete.category || (athlete.profileComplete ? '—' : 'Profile pending')} · {athlete.status}</p></div>{!athlete.profileComplete && <span className="hidden shrink-0 rounded-md bg-accent/15 px-2 py-1 text-[9px] font-extrabold uppercase text-accent sm:block">Awaiting sign-in</span>}<div className="hidden shrink-0 text-right sm:block"><p className="font-mono text-xs">{athlete.progress > 0 ? '+' : ''}{athlete.progress}%</p><p className="text-[10px] uppercase text-muted-foreground">progress</p></div><ChevronRight className="h-4 w-4 shrink-0 text-muted-foreground" /></Link><button onClick={onEdit} className="shrink-0 rounded-lg px-2 py-1 text-xs font-bold text-muted-foreground hover:bg-muted hover:text-foreground" data-testid={`button-edit-athlete-${athlete.id}`}>Edit</button></div>; }
function DashboardLoading() { return <div className="space-y-6"><Skeleton className="h-32 w-2/3" /><div className="grid gap-4 sm:grid-cols-4">{[1, 2, 3, 4].map(x => <Skeleton key={x} className="h-32" />)}</div><Skeleton className="h-80" /></div>; }
function ErrorState({ retry }: { retry: () => void }) { return <Empty title="Could not load this view" body="The training room is taking a moment. Try again." action={<Button onClick={retry} variant="outline" data-testid="button-retry">Retry</Button>} />; }

function AthletesPage() {
  const { data, isLoading, isError, refetch } = useListAthletes();
  const update = useUpdateAthlete(); const remove = useDeleteAthlete(); const qc = useQueryClient();
  const [search, setSearch] = useState(''); const [modal, setModal] = useState<Athlete | null>(null);
  const filtered = (data || []).filter(a => `${a.firstName} ${a.lastName}`.toLowerCase().includes(search.toLowerCase()));
  const [saveError, setSaveError] = useState('');
  const [copied, setCopied] = useState(false);
  const inviteUrl = typeof window !== 'undefined' ? `${window.location.origin}${window.location.pathname.replace(/\/(login|signup|coach|athletes).*$/, '/')}signup` : '/signup';
  const copyInvite = () => { navigator.clipboard?.writeText(inviteUrl).then(() => { setCopied(true); setTimeout(() => setCopied(false), 2000); }); };
  const save = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!modal) return;
    const f = new FormData(event.currentTarget);
    update.mutate({ id: modal.id, data: { firstName: String(f.get('firstName')), lastName: String(f.get('lastName')), bodyWeight: Number(f.get('bodyWeight')) || null, category: String(f.get('category') || '') || null, records: { squat: Number(f.get('squat')) || null, bench: Number(f.get('bench')) || null, deadlift: Number(f.get('deadlift')) || null }, powerliftingSince: String(f.get('powerliftingSince') || '') || null } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAthletesQueryKey() }); setModal(null); }, onError: () => setSaveError('Could not save this athlete.') });
  };
  const InviteCard = <Card className="mb-5 flex flex-col gap-3 p-4 sm:flex-row sm:items-center sm:justify-between" data-testid="card-invite-athlete">
    <div><p className="text-sm font-bold">Invite an athlete</p><p className="text-xs text-muted-foreground">Share this link — anyone who signs up with it joins your roster as an athlete.</p></div>
    <Button variant="outline" onClick={copyInvite} data-testid="button-copy-invite"><Copy className="h-4 w-4" /> {copied ? 'Copied!' : 'Copy signup link'}</Button>
  </Card>;
  return <div className="sn-enter"><PageHead eyebrow="Roster / 04" title="Athletes" body="The people, the plan, the next strong rep." />{InviteCard}<div className="mb-5 flex items-center gap-3"><div className="relative max-w-sm flex-1"><Search className="absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search roster" className="w-full rounded-xl border border-input bg-card py-2.5 pl-10 pr-3 text-sm outline-none ring-primary focus:ring-2" data-testid="input-search-athletes" /></div><span className="rounded-lg bg-secondary px-3 py-2 text-xs font-mono text-muted-foreground">{filtered.length} athletes</span></div>{isLoading ? <Skeleton className="h-96" /> : isError ? <ErrorState retry={refetch} /> : filtered.length ? <Card className="overflow-hidden"><div className="hidden grid-cols-[1fr_150px_130px_100px_24px] gap-4 border-b border-border bg-muted/40 px-5 py-3 text-[10px] font-bold uppercase tracking-[.16em] text-muted-foreground md:grid"><span>Athlete</span><span>Next session</span><span>Last touch</span><span>Progress</span><span /></div>{filtered.map(a => <AthleteRow key={a.id} athlete={a} onEdit={() => setModal(a)} />)}</Card> : <Empty title={search ? 'No match in the roster' : 'Start your roster'} body="Share your invite link above and athletes will appear here once they sign up." />}{modal && <Modal title="Edit athlete" close={() => setModal(null)}><form onSubmit={save} className="space-y-4">{['firstName', 'lastName', 'category', 'bodyWeight'].map(field => <label key={field} className="block"><span className="mb-1.5 block text-xs font-bold capitalize text-muted-foreground">{field === 'bodyWeight' ? 'Body weight (kg)' : field}</span><input name={field} defaultValue={modal[field as keyof Athlete] != null ? String(modal[field as keyof Athlete]) : ''} type={field === 'bodyWeight' ? 'number' : 'text'} required={['firstName', 'lastName'].includes(field)} className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid={`input-athlete-${field}`} /></label>)}<RecordsFields user={modal} isAthlete /><p className="text-xs text-muted-foreground">Password changes are made by the athlete from their own account, not here.</p>{saveError && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive" data-testid="status-athlete-error">{saveError}</p>}<Button className="w-full" type="submit" disabled={update.isPending} data-testid="button-save-athlete">{update.isPending ? 'Saving…' : 'Save athlete'}</Button><Button type="button" variant="danger" className="w-full" onClick={() => { if (confirm('Delete this athlete?')) remove.mutate({ id: modal.id }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListAthletesQueryKey() }); setModal(null); } }); }} data-testid="button-delete-athlete">Delete athlete</Button></form></Modal>}</div>;
}
function Modal({ title, close, children }: { title: string; close: () => void; children: ReactNode }) { return <div className="fixed inset-0 z-50 grid place-items-center bg-foreground/35 p-4 backdrop-blur-sm"><div className="w-full max-w-md rounded-2xl border border-border bg-card p-6 shadow-xl sn-enter"><div className="mb-5 flex items-center justify-between"><h2 className="text-xl font-extrabold">{title}</h2><button onClick={close} data-testid="button-modal-close"><X className="h-5 w-5" /></button></div>{children}</div></div>; }

function AthleteWorkspace() { const { id } = useParams(); const athleteId = Number(id); const { data: athlete, isLoading } = useGetAthlete(athleteId); const { data: sessions } = useListSessions(athleteId); const { data: stats } = useGetAthleteStats(athleteId); if (isLoading) return <DashboardLoading />; if (!athlete) return <ErrorState retry={() => undefined} />; return <div className="sn-enter"><PageHead eyebrow={`Athlete / ${athlete.id}`} title={`${athlete.firstName} ${athlete.lastName}`} body={`${athlete.category || 'Powerlifting'} · ${athlete.bodyWeight || '—'} kg bodyweight`} action={<Link href={`/athletes/${athlete.id}/program`} className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-athlete-program">Open program <ArrowRight className="h-4 w-4" /></Link>} /><div className="grid gap-4 sm:grid-cols-3"><Stat label="Best squat" value={`${stats?.squat?.best1rm || '—'} kg`} detail="estimated 1RM" /><Stat label="Best bench" value={`${stats?.bench?.best1rm || '—'} kg`} detail="estimated 1RM" tone="accent" /><Stat label="Best deadlift" value={`${stats?.deadlift?.best1rm || '—'} kg`} detail="estimated 1RM" tone="teal" /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_350px]"><Card className="p-5"><div className="flex justify-between"><div><h2 className="font-extrabold">Training timeline</h2><p className="mt-1 text-xs text-muted-foreground">Recent and upcoming sessions</p></div><Link href={`/athletes/${athlete.id}/program`} className="text-xs font-bold text-accent" data-testid="link-workspace-program">View program</Link></div><div className="mt-5 space-y-3">{(sessions || []).slice(0, 6).map(s => <SessionRow key={s.id} session={s} />)}{!sessions?.length && <Empty title="No sessions yet" body="Build the first block for this athlete." action={<Link href={`/athletes/${athlete.id}/program`} className="text-sm font-bold text-accent">Open program</Link>} />}</div></Card><Card className="sn-grid p-5"><p className="font-mono text-[10px] uppercase tracking-[.18em] text-accent">Coach note</p><h2 className="mt-3 text-xl font-extrabold">Stay one rep ahead.</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">Use the program view to manage intent, then let the session log tell you what actually happened.</p></Card></div></div>; }
function SessionRow({ session }: { session: TrainingSession }) { return <Link href={`/sessions/${session.id}`} className="flex items-center gap-3 rounded-xl border border-border p-3 hover:bg-muted" data-testid={`row-session-${session.id}`}><div className={cx('grid h-9 w-9 place-items-center rounded-lg text-xs font-bold', session.status === 'completed' ? 'bg-chart-3/15 text-chart-3' : 'bg-primary/20 text-foreground')}>{session.weekNumber}</div><div className="min-w-0 flex-1"><p className="truncate text-sm font-bold">{session.name}</p><p className="text-xs text-muted-foreground">{dateLabel(session.sessionDate)} · {session.exercises?.length || 0} exercises</p></div><span className="rounded-md bg-secondary px-2 py-1 text-[10px] font-bold uppercase">{session.status.replace('_', ' ')}</span><ChevronRight className="h-4 w-4 text-muted-foreground" /></Link>; }

function ProgramPage() { const { id } = useParams(); const athleteId = Number(id); const { data: athlete } = useGetAthlete(athleteId); const { data: program, isLoading } = useGetProgram(athleteId); const createSession = useCreateSession(); const qc = useQueryClient(); const [add, setAdd] = useState(false); if (isLoading) return <DashboardLoading />; const blocks = program?.blocks || []; const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); createSession.mutate({ athleteId, data: { name: String(f.get('name')), sessionDate: String(f.get('sessionDate')), weekNumber: Number(f.get('weekNumber')), notes: null, exercises: [] } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getGetProgramQueryKey(athleteId) }); setAdd(false); } }); }; return <div className="sn-enter"><PageHead eyebrow={`Program / ${athlete?.firstName || 'Athlete'}`} title={program?.name || 'Current program'} body={`${program?.method || 'Structured strength'} · training maxes are live`} action={<Button onClick={() => setAdd(true)} data-testid="button-add-session"><Plus className="h-4 w-4" /> New session</Button>} /><div className="mb-6 flex flex-wrap gap-2">{Object.entries(program?.trainingMaxes || {}).map(([k, v]) => <div key={k} className="rounded-xl border border-border bg-card px-4 py-3"><p className="text-[10px] font-bold uppercase text-muted-foreground">{k} TM</p><p className="mt-1 font-mono text-lg font-bold">{String(v)} <span className="text-xs font-normal">kg</span></p></div>)}</div>{blocks.length ? <div className="space-y-5">{blocks.map(block => <Card key={block.id} className="overflow-hidden"><div className="flex items-center justify-between border-b border-border bg-muted/30 px-5 py-4"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-accent">Week {block.weekNumber}</p><h2 className="mt-1 font-extrabold">{block.name}</h2></div><span className="text-xs text-muted-foreground">{block.sessions.length} sessions</span></div><div className="grid gap-3 p-4 md:grid-cols-2">{block.sessions.map(s => <SessionRow key={s.id} session={s} />)}</div></Card>)}</div> : <Empty title="Program canvas is clear" body="Add a session to begin shaping this athlete's week." action={<Button onClick={() => setAdd(true)} data-testid="button-empty-add-session"><Plus className="h-4 w-4" /> Add first session</Button>} />}{add && <Modal title="New training session" close={() => setAdd(false)}><form onSubmit={submit} className="space-y-4">{[['name','Session name','text'],['sessionDate','Date','date'],['weekNumber','Week number','number']].map(([name,label,type]) => <label key={name} className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{label}</span><input name={name} type={type} defaultValue={name === 'weekNumber' ? '1' : undefined} required className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm" data-testid={`input-session-${name}`} /></label>)}<Button className="w-full" type="submit" data-testid="button-save-session">Create session</Button></form></Modal>}</div>; }

function SessionPage() { const { id } = useParams(); const sessionId = Number(id); const { data: session, isLoading } = useGetSession(sessionId); const update = useUpdateSession(); const addExercise = useAddExercise(); const updateExercise = useUpdateExercise(); const deleteExercise = useDeleteExercise(); const deleteSession = useDeleteSession(); const log = useLogExercise(); const qc = useQueryClient(); const [, setLocation] = useLocation(); const [adding, setAdding] = useState(false); if (isLoading) return <DashboardLoading />; if (!session) return <ErrorState retry={() => undefined} />; const refresh = () => qc.invalidateQueries({ queryKey: getGetSessionQueryKey(sessionId) }); const saveStatus = (status: string) => update.mutate({ id: sessionId, data: { status: status as 'planned' | 'in_progress' | 'completed' } }, { onSuccess: refresh }); const add = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); addExercise.mutate({ sessionId, data: { name: String(f.get('name')), category: String(f.get('category')), order: session.exercises.length, sets: Number(f.get('sets')), reps: Number(f.get('reps')), loadMode: 'fixed', loadValue: Number(f.get('loadValue')) || null, percentage: null, targetRpe: Number(f.get('targetRpe')) || null, restSeconds: 180, tempo: null, notes: null } }, { onSuccess: () => { refresh(); setAdding(false); } }); }; return <div className="sn-enter"><PageHead eyebrow={`Session / Week ${session.weekNumber}`} title={session.name} body={`${dateLabel(session.sessionDate)} · ${session.exercises.length} exercises`} action={<div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => saveStatus('in_progress')} data-testid="button-start-session">Start session</Button><Button onClick={() => saveStatus('completed')} data-testid="button-complete-session"><Check className="h-4 w-4" /> Complete</Button><Button variant="danger" onClick={() => { if (confirm('Delete this session?')) deleteSession.mutate({ id: sessionId }, { onSuccess: () => setLocation(`/athletes/${session.athleteId}/program`) }); }} data-testid="button-delete-session">Delete</Button></div>} /><div className="grid gap-6 lg:grid-cols-[1fr_300px]"><div className="space-y-3">{session.exercises.map((ex, i) => <ExerciseCard key={ex.id} exercise={ex} index={i} onLog={(payload) => log.mutate({ id: ex.id, data: payload }, { onSuccess: refresh })} onDelete={() => { if (confirm('Remove this exercise?')) deleteExercise.mutate({ id: ex.id }, { onSuccess: refresh }); }} onUpdate={(data) => updateExercise.mutate({ id: ex.id, data }, { onSuccess: refresh })} />)}<Button variant="outline" className="w-full border-dashed py-4" onClick={() => setAdding(true)} data-testid="button-add-exercise"><Plus className="h-4 w-4" /> Add exercise</Button></div><Card className="h-fit p-5"><p className="font-mono text-[10px] uppercase tracking-[.16em] text-accent">Session brief</p><textarea defaultValue={session.notes || ''} onBlur={e => update.mutate({ id: sessionId, data: { notes: e.target.value } }, { onSuccess: refresh })} placeholder="Add a note for this session…" className="mt-4 min-h-32 w-full resize-none rounded-xl border border-input bg-background p-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="textarea-session-notes" /><div className="mt-5 border-t border-border pt-4"><p className="text-xs font-bold text-muted-foreground">Status</p><p className="mt-2 text-sm font-bold capitalize">{session.status.replace('_', ' ')}</p></div></Card></div>{adding && <Modal title="Add exercise" close={() => setAdding(false)}><form onSubmit={add} className="space-y-4">{[['name','Exercise','text'],['category','Category','text'],['sets','Sets','number'],['reps','Reps','number'],['loadValue','Load (kg)','number'],['targetRpe','Target RPE','number']].map(([n,l,t]) => <label key={n} className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{l}</span><input name={n} type={t} defaultValue={['sets','reps'].includes(n) ? '3' : undefined} required={['name','category','sets','reps'].includes(n)} className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm" data-testid={`input-exercise-${n}`} /></label>)}<Button className="w-full" type="submit" data-testid="button-save-exercise">Add exercise</Button></form></Modal>}</div>; }
function ExerciseCard({ exercise, index, onLog, onDelete, onUpdate }: { exercise: Exercise; index: number; onLog: (x: { actualLoad: number; actualReps: number; actualRpe?: number | null; comment?: string | null }) => void; onDelete: () => void; onUpdate: (x: { notes?: string | null }) => void }) { const [load, setLoad] = useState(exercise.actualLoad?.toString() || exercise.loadValue?.toString() || ''); const [reps, setReps] = useState(exercise.actualReps?.toString() || exercise.reps.toString()); return <Card className={cx('p-4', exercise.completed && 'border-chart-3/50 bg-chart-3/5')}><div className="flex items-start gap-3"><div className="grid h-9 w-9 shrink-0 place-items-center rounded-lg bg-secondary font-mono text-xs font-bold">{String(index + 1).padStart(2, '0')}</div><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><div><h3 className="font-extrabold">{exercise.name}</h3><p className="mt-1 text-xs text-muted-foreground">{exercise.sets} sets × {exercise.reps} reps · {exercise.loadMode === 'fixed' ? `${exercise.loadValue || '—'} kg` : exercise.loadMode}</p></div><button onClick={onDelete} className="text-muted-foreground hover:text-destructive" data-testid={`button-delete-exercise-${exercise.id}`}><X className="h-4 w-4" /></button></div><div className="mt-4 grid grid-cols-[1fr_1fr_auto] gap-2"><input value={load} onChange={e => setLoad(e.target.value)} type="number" placeholder="Load kg" className="rounded-lg border border-input bg-background px-3 py-2 text-sm" data-testid={`input-log-load-${exercise.id}`} /><input value={reps} onChange={e => setReps(e.target.value)} type="number" placeholder="Reps" className="rounded-lg border border-input bg-background px-3 py-2 text-sm" data-testid={`input-log-reps-${exercise.id}`} /><Button onClick={() => onLog({ actualLoad: Number(load), actualReps: Number(reps) })} className="px-3" data-testid={`button-log-exercise-${exercise.id}`}><Check className="h-4 w-4" /> Log</Button></div><input defaultValue={exercise.notes || ''} onBlur={e => onUpdate({ notes: e.target.value })} placeholder="Optional cue or note" className="mt-2 w-full border-0 border-b border-border bg-transparent py-2 text-xs outline-none" data-testid={`input-exercise-note-${exercise.id}`} /></div></div></Card>; }

function CalendarPage() { const { data: athletes } = useListAthletes(); const first = athletes?.[0]; const { data: sessions } = useListSessions(first?.id || 0, { query: { enabled: !!first?.id, queryKey: getListSessionsQueryKey(first?.id || 0) } }); const days = Array.from({ length: 14 }, (_, i) => { const d = new Date(); d.setDate(d.getDate() + i - 2); return d; }); return <div className="sn-enter"><PageHead eyebrow="Planning / 14 days" title="Calendar" body="See the week before it arrives." /><div className="mb-5 flex gap-2 overflow-auto pb-1">{days.map((d, i) => <div key={i} className={cx('min-w-[86px] rounded-2xl border p-3', i === 2 ? 'border-primary bg-primary text-primary-foreground' : 'border-border bg-card')}><p className="font-mono text-[10px] uppercase opacity-65">{d.toLocaleDateString(undefined, { weekday: 'short' })}</p><p className="mt-2 text-2xl font-extrabold">{d.getDate()}</p><p className="mt-1 text-[10px] opacity-65">{i === 2 ? 'TODAY' : `${(sessions || []).filter(s => new Date(s.sessionDate).toDateString() === d.toDateString()).length} sessions`}</p></div>)}</div><Card className="p-5"><div className="grid gap-3 md:grid-cols-2">{(sessions || []).map(s => <SessionRow key={s.id} session={s} />)}</div>{!sessions?.length && <Empty title="No sessions in view" body="Your next programmed work will appear here." />}</Card></div>; }

function ExercisesPage() { const { data, isLoading } = useListExerciseLibrary(); const create = useCreateExerciseLibraryItem(); const qc = useQueryClient(); const [adding, setAdding] = useState(false); const [search, setSearch] = useState(''); const items = (data || []).filter((x: ExerciseLibraryItem) => x.name.toLowerCase().includes(search.toLowerCase())); const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); create.mutate({ data: { name: String(f.get('name')), category: String(f.get('category')), isMainLift: f.get('isMainLift') === 'on' } }, { onSuccess: () => { qc.invalidateQueries({ queryKey: getListExerciseLibraryQueryKey() }); setAdding(false); } }); }; return <div className="sn-enter"><PageHead eyebrow="Library / Movement index" title="Exercise library" body="A clean vocabulary for strong work." action={<Button onClick={() => setAdding(true)} data-testid="button-add-library-exercise"><Plus className="h-4 w-4" /> Add movement</Button>} /><input value={search} onChange={e => setSearch(e.target.value)} placeholder="Search movements" className="mb-5 w-full max-w-sm rounded-xl border border-input bg-card px-3 py-2.5 text-sm" data-testid="input-search-exercises" />{isLoading ? <Skeleton className="h-80" /> : items.length ? <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{items.map(x => <Card key={x.id} className="flex items-center gap-3 p-4" data-testid={`card-library-exercise-${x.id}`}><div className="grid h-10 w-10 place-items-center rounded-xl bg-secondary"><Dumbbell className="h-4 w-4" /></div><div className="min-w-0 flex-1"><p className="font-bold">{x.name}</p><p className="text-xs text-muted-foreground">{x.category}</p></div>{x.isMainLift && <span className="rounded-md bg-primary/20 px-2 py-1 text-[9px] font-extrabold uppercase">Main lift</span>}</Card>)}</div> : <Empty title="No movements found" body="Create a movement to make it available in your sessions." action={<Button onClick={() => setAdding(true)}>Add movement</Button>} />}{adding && <Modal title="New movement" close={() => setAdding(false)}><form onSubmit={submit} className="space-y-4"><input name="name" required placeholder="Movement name" className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm" data-testid="input-library-name" /><input name="category" required placeholder="Category, e.g. squat" className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm" data-testid="input-library-category" /><label className="flex items-center gap-2 text-sm"><input type="checkbox" name="isMainLift" data-testid="input-library-main-lift" /> Main lift</label><Button className="w-full" type="submit" data-testid="button-save-library-exercise">Save movement</Button></form></Modal>}</div>; }

function ProgressPage({ athleteMode = false }: { athleteMode?: boolean }) { const { data: athletes } = useListAthletes(); const user = athletes?.[0]; const { data: stats, isLoading } = useGetAthleteStats(user?.id || 0, { query: { enabled: !!user?.id, queryKey: getGetAthleteStatsQueryKey(user?.id || 0) } }); const lifts = stats ? [['Squat', stats.squat], ['Bench press', stats.bench], ['Deadlift', stats.deadlift]] as [string, Stats['squat']][] : []; return <div className="sn-enter"><PageHead eyebrow={athleteMode ? 'My training / Progress' : 'Analytics / Roster'} title={athleteMode ? 'Progress you can feel.' : 'Progress'} body="Strength is a trend, not a single number." /><div className="grid gap-4 sm:grid-cols-3"><Stat label="Total volume" value={`${((stats?.totalVolume || 0) / 1000).toFixed(1)}k`} detail="kg in selected period" /><Stat label="Tonnage" value={`${((stats?.totalTonnage || 0) / 1000).toFixed(1)}k`} detail="total work performed" tone="accent" /><Stat label="Body weight" value={`${stats?.bodyWeight || '—'} kg`} detail={stats?.period || 'Current period'} tone="teal" /></div><Card className="mt-6 p-5"><div className="flex items-center justify-between"><div><h2 className="font-extrabold">Lift profile</h2><p className="mt-1 text-xs text-muted-foreground">Best estimated 1RM, 3RM, and 5RM.</p></div><BarChart3 className="h-5 w-5 text-muted-foreground" /></div>{isLoading ? <Skeleton className="mt-5 h-48" /> : <div className="mt-6 space-y-5">{lifts.map(([name, lift]) => <div key={name}><div className="mb-2 flex items-center justify-between"><p className="font-bold">{name}</p><p className="font-mono text-sm">{lift.best1rm} kg <span className="text-xs text-muted-foreground">1RM</span></p></div><div className="flex h-12 items-end gap-1 rounded-lg bg-muted p-2">{(lift.trend || []).slice(-12).map((point, i) => <div key={i} className="flex-1 rounded-t bg-primary/75" style={{ height: `${Math.max(12, Math.min(100, (point.value / Math.max(lift.best1rm, 1)) * 100))}%` }} title={`${point.value} kg`} />)}</div><div className="mt-2 flex gap-4 text-xs text-muted-foreground"><span>3RM <b className="text-foreground">{lift.best3rm} kg</b></span><span>5RM <b className="text-foreground">{lift.best5rm} kg</b></span></div></div>)}</div>}{!isLoading && !lifts.length && <Empty title="Progress follows the work" body="Once sessions are logged, your lift profile will take shape." />}</Card></div>; }

function SettingsPage() {
  const { data: user } = useGetCurrentUser();
  const [theme, setTheme] = useState(localStorage.getItem('sn-theme') || 'light'); const [saved, setSaved] = useState(false); const set = (v: string) => { setTheme(v); if (v === 'system') document.documentElement.classList.toggle('dark', matchMedia('(prefers-color-scheme: dark)').matches); else document.documentElement.classList.toggle('dark', v === 'dark'); localStorage.setItem('sn-theme', v); setSaved(true); };
  const complete = useCompleteProfile(); const [profileSaved, setProfileSaved] = useState(false); const [profileError, setProfileError] = useState('');
  const saveProfile = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault(); setProfileSaved(false); setProfileError('');
    const f = new FormData(e.currentTarget);
    complete.mutate({ data: { category: String(f.get('category') || '') || null, bodyWeight: Number(f.get('bodyWeight')) || null, records: { squat: Number(f.get('squat')) || null, bench: Number(f.get('bench')) || null, deadlift: Number(f.get('deadlift')) || null }, powerliftingSince: String(f.get('powerliftingSince') || '') || null } }, { onSuccess: () => setProfileSaved(true), onError: () => setProfileError('Could not save your profile.') });
  };
  return <div className="sn-enter max-w-3xl"><PageHead eyebrow="Workspace / Preferences" title="Settings" body="Make SN Power fit the way you train." />{saved && <div className="mb-5 flex items-center gap-2 rounded-xl border border-chart-3/30 bg-chart-3/10 px-4 py-3 text-sm font-semibold text-chart-3"><Check className="h-4 w-4" /> Preferences saved</div>}
    {user && <Card className="mb-4 p-5"><h2 className="font-extrabold">Personal records</h2><p className="mt-1 text-sm text-muted-foreground">{user.role === 'athlete' ? 'Keep your weight class, body weight, and current maxes up to date.' : 'Your own training background, if you lift too.'}</p><form onSubmit={saveProfile} className="mt-5 space-y-4"><div className="grid gap-4 sm:grid-cols-2"><label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">{user.role === 'athlete' ? 'Weight class / category' : 'Coaching focus'}</span><input name="category" defaultValue={user.category ?? ''} className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-settings-category" /></label><label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Body weight (kg)</span><input name="bodyWeight" type="number" step="0.1" defaultValue={user.bodyWeight ?? ''} className="w-full rounded-xl border border-input bg-background px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-settings-bodyweight" /></label></div><RecordsFields user={user} isAthlete={user.role === 'athlete'} />{profileError && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive">{profileError}</p>}<div className="flex items-center gap-3"><Button type="submit" disabled={complete.isPending} data-testid="button-save-records">{complete.isPending ? 'Saving…' : 'Save records'}</Button>{profileSaved && <span className="flex items-center gap-1.5 text-xs font-semibold text-chart-3"><Check className="h-3.5 w-3.5" /> Saved</span>}</div></form></Card>}
    <Card className="p-5"><h2 className="font-extrabold">Appearance</h2><p className="mt-1 text-sm text-muted-foreground">Choose a visual mode for long training weeks.</p><div className="mt-5 grid gap-3 sm:grid-cols-3">{[['light','Light',Sun],['dark','Dark',Moon],['system','System',SettingsIcon]].map(([id,label,Icon]) => <button key={id as string} onClick={() => set(id as string)} className={cx('flex items-center gap-3 rounded-xl border p-4 text-left', theme === id ? 'border-primary bg-primary/10' : 'border-border hover:bg-muted')} data-testid={`button-theme-${id}`}><Icon className="h-5 w-5" /><span><span className="block text-sm font-bold">{label as string}</span><span className="text-xs text-muted-foreground">{id === 'system' ? 'Follow device' : `${label as string} canvas`}</span></span>{theme === id && <Check className="ml-auto h-4 w-4 text-accent" />}</button>)}</div></Card><Card className="mt-4 p-5"><h2 className="font-extrabold">Training preferences</h2><div className="mt-5 divide-y divide-border"><label className="flex items-center justify-between py-3 text-sm"><span><b className="block">Show metric units</b><span className="text-xs text-muted-foreground">Use kg and metres across the workspace</span></span><input type="checkbox" defaultChecked className="h-4 w-4 accent-primary" data-testid="input-metric-units" /></label><label className="flex items-center justify-between py-3 text-sm"><span><b className="block">Session reminders</b><span className="text-xs text-muted-foreground">Keep upcoming work visible</span></span><input type="checkbox" defaultChecked className="h-4 w-4 accent-primary" data-testid="input-session-reminders" /></label></div></Card></div>;
}

function AuthShell({ eyebrow, title, children }: { eyebrow: string; title: ReactNode; children: ReactNode }) {
  return <div className="sn-grid min-h-[100dvh] bg-background p-5 md:p-10"><div className="mx-auto flex min-h-[calc(100dvh-40px)] max-w-6xl items-center justify-center md:justify-between md:gap-12">
    <div className="hidden max-w-md md:block"><Logo /><p className="mt-14 font-mono text-[10px] uppercase tracking-[.2em] text-accent">A calmer way to get strong</p><h1 className="mt-4 text-5xl font-extrabold leading-[1.02] tracking-[-.06em]">Train the<br /><span className="text-accent">signal.</span></h1><p className="mt-6 max-w-sm text-sm leading-6 text-muted-foreground">SN Power keeps the plan, the session, and the coaching conversation in one precise place.</p><div className="mt-16 flex gap-2"><span className="h-2 w-16 rounded-full bg-primary" /><span className="h-2 w-8 rounded-full bg-accent" /><span className="h-2 w-3 rounded-full bg-chart-3" /></div></div>
    <Card className="w-full max-w-md p-7 md:p-9"><div className="mb-8 md:hidden"><Logo /></div><p className="font-mono text-[10px] uppercase tracking-[.2em] text-accent">{eyebrow}</p><h2 className="mt-2 text-3xl font-extrabold tracking-[-.04em]">{title}</h2>{children}</Card>
  </div></div>;
}

function SignupPage() {
  const setup = useGetSetupStatus();
  const register = useRegister();
  const [, setLocation] = useLocation();
  const [error, setError] = useState('');
  const submit = (e: FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    const f = new FormData(e.currentTarget);
    const password = String(f.get('password'));
    const confirm = String(f.get('confirmPassword'));
    if (password !== confirm) { setError('Passwords do not match.'); return; }
    if (password.length < 6) { setError('Use at least 6 characters for your password.'); return; }
    register.mutate({ data: { firstName: String(f.get('firstName')), lastName: String(f.get('lastName')), username: String(f.get('username')), password } }, { onSuccess: () => setLocation('/coach'), onError: e2 => setError(e2 instanceof Error ? e2.message : 'Could not create the account.') });
  };
  const isFirstAccount = setup.data?.needsSetup;
  return <AuthShell eyebrow={isFirstAccount ? 'First run · this device' : 'Join the roster'} title={isFirstAccount ? 'Set up your coach account.' : 'Create your athlete account.'}>
    <p className="mt-2 text-sm text-muted-foreground">{isFirstAccount ? 'This workspace has no account yet. Create the one real coach login for this browser — everything you enter from here on (athletes, sessions, stats) is saved for real, on this device.' : 'Your coach will find your profile in their roster right after you sign in for the first time.'}</p>
    <form onSubmit={submit} className="mt-8 space-y-4">
      <div className="grid grid-cols-2 gap-3">
        <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">First name</span><input name="firstName" autoComplete="given-name" required className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-signup-firstname" /></label>
        <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Last name</span><input name="lastName" autoComplete="family-name" required className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-signup-lastname" /></label>
      </div>
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Username</span><input name="username" autoComplete="username" required placeholder="Choose a username" className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-signup-username" /></label>
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Password</span><input name="password" autoComplete="new-password" type="password" required placeholder="At least 6 characters" className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-signup-password" /></label>
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Confirm password</span><input name="confirmPassword" autoComplete="new-password" type="password" required className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-signup-confirm-password" /></label>
      {error && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive" data-testid="status-signup-error">{error}</p>}
      <Button className="w-full py-3" type="submit" disabled={register.isPending} data-testid="button-signup-submit">{register.isPending ? 'Creating account…' : isFirstAccount ? 'Create my coach account' : 'Create my account'}</Button>
    </form>
    <p className="mt-6 text-center text-sm text-muted-foreground">Already have an account? <Link href="/login" className="font-bold text-accent">Sign in</Link></p>
  </AuthShell>;
}

function LoginPage() {
  const login = useLogin();
  const [, setLocation] = useLocation();
  const [error, setError] = useState('');
  const submit = (e: FormEvent<HTMLFormElement>) => { e.preventDefault(); const f = new FormData(e.currentTarget); login.mutate({ data: { username: String(f.get('username')), password: String(f.get('password')) } }, { onSuccess: user => setLocation(user.role === 'athlete' ? '/athlete' : '/coach'), onError: () => setError('Incorrect username or password.') }); };
  return <AuthShell eyebrow="Welcome back" title="Open your workspace.">
    <p className="mt-2 text-sm text-muted-foreground">Sign in to pick up where the work left off.</p>
    <form onSubmit={submit} className="mt-8 space-y-4">
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Username</span><input name="username" autoComplete="username" required className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-login-username" /></label>
      <label className="block"><span className="mb-1.5 block text-xs font-bold text-muted-foreground">Password</span><input name="password" autoComplete="current-password" type="password" required className="w-full rounded-xl border border-input bg-background px-3 py-3 text-sm outline-none focus:ring-2 focus:ring-primary" data-testid="input-login-password" /></label>
      {error && <p className="rounded-lg bg-destructive/10 p-3 text-xs font-semibold text-destructive" data-testid="status-login-error">{error}</p>}
      <Button className="w-full py-3" type="submit" disabled={login.isPending} data-testid="button-login">{login.isPending ? 'Signing in…' : 'Sign in'}</Button>
    </form>
    <p className="mt-6 text-center text-sm text-muted-foreground">No account yet? <Link href="/signup" className="font-bold text-accent">Create one</Link></p>
  </AuthShell>;
}

function AthleteToday() { const { data: athletes } = useListAthletes(); const athleteId = athletes?.[0]?.id || 0; const { data: sessions } = useListSessions(athleteId, { query: { enabled: !!athleteId, queryKey: getListSessionsQueryKey(athleteId) } }); const today = sessions?.find(session => session.status !== 'completed') || sessions?.[0]; return <div className="sn-enter"><PageHead eyebrow="Today / Training day" title="Make today count." body="Your plan is ready when you are." action={today ? <Link href={`/sessions/${today.id}`} className="inline-flex items-center gap-2 rounded-xl bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-start-today">Open today's session <ArrowRight className="h-4 w-4" /></Link> : undefined} />{today ? <div className="grid gap-6 lg:grid-cols-[1fr_300px]"><Card className="p-5"><div className="flex items-center justify-between border-b border-border pb-4"><div><p className="font-mono text-[10px] uppercase tracking-[.16em] text-accent">Next up</p><h2 className="mt-1 text-2xl font-extrabold">{today.name}</h2></div><span className="rounded-lg bg-primary/20 px-3 py-2 font-mono text-xs">WEEK {today.weekNumber}</span></div><div className="mt-5 space-y-3">{today.exercises.map((x, i) => <div className="flex items-center gap-3 rounded-xl bg-muted/60 p-3" key={x.id}><span className="font-mono text-xs text-muted-foreground">{String(i + 1).padStart(2, '0')}</span><span className="flex-1 text-sm font-bold">{x.name}</span><span className="text-xs text-muted-foreground">{x.sets} × {x.reps}</span></div>)}</div></Card><Card className="sn-grid h-fit p-5"><Flame className="h-5 w-5 text-accent" /><h3 className="mt-4 font-extrabold">Own the tempo.</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">Log every set. The useful part of training is what you can remember.</p></Card></div> : <Empty title="No session queued" body="Your coach has not assigned today's work yet." />}</div>; }
function InstallPage() { return <div className="mx-auto max-w-2xl py-10 text-center sn-enter"><Logo /><div className="mx-auto mt-16 grid h-20 w-20 place-items-center rounded-3xl bg-primary text-primary-foreground"><Dumbbell className="h-9 w-9" /></div><p className="mt-8 font-mono text-[10px] uppercase tracking-[.2em] text-accent">Built for the training floor</p><h1 className="mt-3 text-4xl font-extrabold tracking-[-.05em]">Keep SN Power close.</h1><p className="mx-auto mt-4 max-w-md text-sm leading-6 text-muted-foreground">Install the workspace to open your sessions faster and keep your coaching tools one tap away.</p><Card className="mx-auto mt-8 max-w-md p-5 text-left"><div className="flex gap-3"><span className="grid h-8 w-8 place-items-center rounded-lg bg-secondary font-mono text-xs font-bold">01</span><div><h3 className="text-sm font-bold">Open your browser menu</h3><p className="mt-1 text-xs text-muted-foreground">Choose “Add to home screen” or “Install SN Power”.</p></div></div><div className="mt-4 flex gap-3 border-t border-border pt-4"><span className="grid h-8 w-8 place-items-center rounded-lg bg-secondary font-mono text-xs font-bold">02</span><div><h3 className="text-sm font-bold">Keep training</h3><p className="mt-1 text-xs text-muted-foreground">Your workspace will open like a focused training app.</p></div></div></Card><Link href="/coach" className="mt-8 inline-flex items-center gap-2 text-sm font-bold text-accent" data-testid="link-install-back">Back to workspace <ArrowRight className="h-4 w-4" /></Link></div>; }

function Home() { const { data: user, isLoading } = useGetCurrentUser({ query: { queryKey: getGetCurrentUserQueryKey() } }); if (isLoading) return <div className="grid min-h-[100dvh] place-items-center"><Skeleton className="h-12 w-48" /></div>; return <Redirect to={user?.role === 'athlete' ? '/athlete' : user ? '/coach' : '/login'} />; }
function AppRoutes() { return <Switch><Route path="/" component={Home} /><Route path="/login" component={LoginPage} /><Route path="/signup" component={SignupPage} /><Route path="/install" component={InstallPage} /><Route path="/athlete" component={() => <Shell><AthleteToday /></Shell>} /><Route path="/athlete/session" component={() => <Shell><AthleteToday /></Shell>} /><Route path="/athlete/progress" component={() => <Shell><ProgressPage athleteMode /></Shell>} /><Route path="/coach" component={() => <Shell><CoachDashboard /></Shell>} /><Route path="/athletes" component={() => <Shell><AthletesPage /></Shell>} /><Route path="/athletes/:id/program" component={() => <Shell><ProgramPage /></Shell>} /><Route path="/athletes/:id" component={() => <Shell><AthleteWorkspace /></Shell>} /><Route path="/sessions/:id" component={() => <Shell><SessionPage /></Shell>} /><Route path="/calendar" component={() => <Shell><CalendarPage /></Shell>} /><Route path="/exercises" component={() => <Shell><ExercisesPage /></Shell>} /><Route path="/progress" component={() => <Shell><ProgressPage /></Shell>} /><Route path="/settings" component={() => <Shell><SettingsPage /></Shell>} /><Route><Shell><Empty title="Page not found" body="This route is not part of the training plan." action={<Link href="/coach" className="font-bold text-accent">Back to overview</Link>} /></Shell></Route></Switch>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><WouterRouter base={import.meta.env.BASE_URL.replace(/\/$/, '')}><ErrorBoundary><AppRoutes /></ErrorBoundary></WouterRouter><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;